SELECT q.Name, q.Title, q.Mode,
       (SELECT COUNT(*) FROM OPENJSON(q.ColumnsJson)) AS ColCount,
       LEFT(JSON_VALUE(q.QueryJson, '$.CustomQuery'), 80) AS CustomQueryHead
FROM system.SavedQuery q
WHERE q.Name IN (
    N'partextrainfo_listinfo',
    N'vw_PartextrainfoOilInject',
    N'vw_PartextrainfoOilFree',
    N'vw_PartextrainfoDerayer',
    N'vw_PartextrainfoPsa',
    N'vw_PartextrainfoStatic'
)
ORDER BY q.Id;

SELECT q.Name, JSON_VALUE(j.value, '$.Alliance') AS Alliance, JSON_VALUE(j.value, '$.DisplayName') AS DisplayName
FROM system.SavedQuery q
CROSS APPLY OPENJSON(q.ColumnsJson) j
WHERE q.Name = N'partextrainfo_listinfo'
ORDER BY CAST(j.[key] AS int);
